<script setup>
import {ref,onMounted} from 'vue';import AppShell from '../components/AppShell.vue';import {supabase} from '../services/supabase';const theme=ref('light'),emailAlerts=ref(true),applicationAlerts=ref(true),jobAlerts=ref(true),publicProfile=ref(true),message=ref(''),error=ref(''),saving=ref(false);onMounted(async()=>{theme.value=localStorage.getItem('campusgig-theme')||'light';const {data:{user}}=await supabase.auth.getUser();const {data}=await supabase.from('profiles').select('preferences,public_profile').eq('id',user.id).maybeSingle();const p=data?.preferences||{};emailAlerts.value=p.emailAlerts??true;applicationAlerts.value=p.applicationAlerts??true;jobAlerts.value=p.jobAlerts??true;publicProfile.value=data?.public_profile??true});function setTheme(){document.documentElement.dataset.theme=theme.value;localStorage.setItem('campusgig-theme',theme.value)}async function save(){saving.value=true;message.value='';error.value='';const {data:{user}}=await supabase.auth.getUser();const {error:e}=await supabase.from('profiles').update({preferences:{emailAlerts:emailAlerts.value,applicationAlerts:applicationAlerts.value,jobAlerts:jobAlerts.value},public_profile:publicProfile.value}).eq('id',user.id);if(e)error.value=e.message;else message.value='Your preferences have been saved.';saving.value=false}async function changePassword(){const email= (await supabase.auth.getUser()).data.user.email;const {error:e}=await supabase.auth.resetPasswordForEmail(email,{redirectTo:`${location.origin}/reset-password`});if(e)error.value=e.message;else message.value='Password reset instructions have been sent to your email.'}
</script>
<template><AppShell title="Settings" subtitle="Make Campus Gig work your way"><template #default><div class="settings-page"><span class="eyebrow">PREFERENCES & CONTROL</span><h1 class="page-title">Settings</h1><p class="page-subtitle">Manage your appearance, notifications and account preferences.</p><div v-if="message" class="alert success">{{message}}</div><div v-if="error" class="alert error">{{error}}</div><section class="card setting-section"><div><h3>Appearance</h3><p class="muted">Choose how Campus Gig looks on this device.</p></div><div class="theme-options"><button :class="{chosen:theme==='light'}" @click="theme='light';setTheme()"><span class="preview light-preview">☀</span><b>Light</b><small>Bright and clear</small></button><button :class="{chosen:theme==='dark'}" @click="theme='dark';setTheme()"><span class="preview dark-preview">☾</span><b>Dark</b><small>Easy on the eyes</small></button></div></section><section class="card setting-section"><div><h3>Notifications</h3><p class="muted">Choose which updates you want to receive in your account.</p></div><div class="switch-list"><label><span><b>Application updates</b><small>When an employer views or changes your application.</small></span><input v-model="applicationAlerts" type="checkbox"></label><label><span><b>New job recommendations</b><small>Updates about new opportunities and relevant roles.</small></span><input v-model="jobAlerts" type="checkbox"></label><label><span><b>Email notifications</b><small>Allow important account updates by email when supported.</small></span><input v-model="emailAlerts" type="checkbox"></label></div></section><section class="card setting-section"><div><h3>Privacy</h3><p class="muted">Control how your profile appears to other members.</p></div><label class="switch-row"><span><b>Allow employers to view my profile</b><small>Helps employers discover suitable student talent.</small></span><input v-model="publicProfile" type="checkbox"></label></section><section class="card setting-section"><div><h3>Security</h3><p class="muted">Keep your account protected.</p></div><button class="btn btn-outline" @click="changePassword">Send password reset email</button></section><div class="save-row"><button class="btn btn-primary" :disabled="saving" @click="save">{{saving?'Saving…':'Save preferences'}}</button></div></div></template></AppShell></template>
<style scoped>.settings-page{max-width:850px;margin:auto}.setting-section{display:grid;grid-template-columns:1fr 1.2fr;gap:25px;margin-top:17px}.setting-section h3{margin:0 0 6px}.setting-section p{font-size:12px;line-height:1.6;margin:0}.theme-options{display:flex;gap:12px}.theme-options button{flex:1;border:2px solid var(--border);border-radius:13px;background:var(--surface);color:var(--text);padding:12px;text-align:left;display:grid;gap:5px}.theme-options button.chosen{border-color:var(--green)}.preview{height:55px;border-radius:8px;display:grid;place-items:center;font-size:22px}.light-preview{background:#f0f4f7;color:#0d3554}.dark-preview{background:#101923;color:#ffc928}.theme-options small,.switch-list small,.switch-row small{display:block;color:var(--muted);font-size:11px;margin-top:3px}.switch-list{display:grid;gap:0}.switch-list label,.switch-row{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:12px 0;border-bottom:1px solid var(--border);font-size:13px}.switch-list label:last-child{border:0}.switch-list input,.switch-row input{accent-color:var(--green);width:18px;height:18px}.save-row{display:flex;justify-content:flex-end;margin-top:18px}@media(max-width:650px){.setting-section{grid-template-columns:1fr}}</style>
